import { useEffect, useState, useContext } from 'react';
import axios from 'axios';
import Result from '../components/Result';
import AuthContext from '../context/AuthContext';

function History() {
  const [resumes, setResumes] = useState([]);
  const [page, setPage] = useState(1);
  const [pages, setPages] = useState(1);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(false);
  const [filters, setFilters] = useState({ from: '', to: '', minScore: '', q: '', limit: 10 });
  const [openId, setOpenId] = useState(null); // which resume is expanded
  const [currentEdit, setCurrentEdit] = useState({});
  const { user } = useContext(AuthContext);

  const STATUS_OPTIONS = ['Not Reviewed', 'Shortlisted', 'Rejected', 'Interview Scheduled', 'Interviewed', 'Offer Extended', 'Hired'];

  useEffect(() => {
    load();
  }, [page, filters]);

  async function load() {
    setLoading(true);
    try {
      const params = { page, limit: filters.limit };
      if (filters.minScore) params.minScore = filters.minScore;
      if (filters.from) params.from = filters.from;
      if (filters.to) params.to = filters.to;
      if (filters.q) params.q = filters.q;

      const res = await axios.get('/api/resume/my', { params, withCredentials: true });
      setResumes(res.data.data);
      // guard: if server returns total 0 but data exists, use data length to avoid confusing UI
      setTotal((res.data.total || res.data.data?.length || 0));
      setPages(res.data.pages || 1);

      // reset open view when filter/page changes
      setOpenId(null);
      setCurrentEdit({});
    } catch (err) {
      console.error('Load error:', err);
      const msg = err?.response?.data?.error || err?.message || 'Failed to load history';
      alert(msg);
    } finally {
      setLoading(false);
    }
  }

  function handleToggle(r) {
    if (openId === r._id) {
      setOpenId(null);
      setCurrentEdit({});
      return;
    }
    setOpenId(r._id);
    setCurrentEdit({ status: r.interviewStatus || 'Not Reviewed', interviewDate: r.interviewDate ? r.interviewDate.slice(0, 10) : '', note: r.interviewNotes || '' });
  }

  async function saveStatus(id) {
    try {
      const payload = { status: currentEdit.status, interviewDate: currentEdit.interviewDate, note: currentEdit.note };
      const res = await axios.post(`http://localhost:5001/api/resume/${id}/status`, payload, { withCredentials: true });
      const updated = res.data.data;
      setResumes(prev => prev.map(r => r._id === id ? updated : r));
      alert('Status updated');
    } catch (err) {
      console.error('Status save error:', err);
      const msg = err?.response?.data?.error || err?.message || 'Failed to update status';
      alert(msg);
    }
  }

  async function retryAI(id) {
    try {
      const res = await axios.post(`http://localhost:5001/api/resume/${id}/reprocess`, {}, { withCredentials: true });
      const updated = res.data.data;
      setResumes(prev => prev.map(r => r._id === id ? updated : r));
      alert('Reprocess successful');
    } catch (err) {
      console.error('Reprocess failed:', err);
      const msg = err?.response?.data?.error || err?.message || 'Reprocess failed';
      alert(msg);
    }
  }

  async function reprocessAllFailed() {
    if (!window.confirm('Reprocess all failed resumes? This may take a while.')) return;
    try {
      const res = await axios.post('http://localhost:5001/api/resume/reprocess-failed', {}, { withCredentials: true, timeout: 0 });
      alert(`Batch reprocess complete: succeeded=${res.data.succeeded}, failed=${res.data.failed}`);
      // reload list
      load();
    } catch (err) {
      console.error('Batch reprocess failed:', err);
      const msg = err?.response?.data?.error || err?.message || 'Batch reprocess failed';
      alert(msg);
    }
  }

  const doExport = async () => {
    try {
      const params = {};
      if (filters.minScore) params.minScore = filters.minScore;
      if (filters.from) params.from = filters.from;
      if (filters.to) params.to = filters.to;
      if (filters.q) params.q = filters.q;

      const res = await axios.get('http://localhost:5001/api/resume/my/export', { params, withCredentials: true, responseType: 'blob' });
      const url = window.URL.createObjectURL(new Blob([res.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', 'resumes_export.csv');
      document.body.appendChild(link);
      link.click();
      link.parentNode.removeChild(link);
    } catch (err) {
      console.error('Export error:', err);
      const msg = err?.response?.data?.error || err?.message || 'Export failed';
      alert('Export failed: ' + msg);
    }
  };

  return (
    <div style={{ padding: 20 }}>
      <h3>Your Resume History</h3>

      <div style={{ display: 'flex', gap: 8, marginBottom: 12 }}>
        <input type="date" value={filters.from} onChange={e => setFilters(f => ({ ...f, from: e.target.value }))} />
        <input type="date" value={filters.to} onChange={e => setFilters(f => ({ ...f, to: e.target.value }))} />
        <input type="number" placeholder="Min score" value={filters.minScore} onChange={e => setFilters(f => ({ ...f, minScore: e.target.value }))} />
        <input type="text" placeholder="Search" value={filters.q} onChange={e => setFilters(f => ({ ...f, q: e.target.value }))} />
        <button onClick={() => { setPage(1); }} className="btn">Apply</button>
        <button onClick={() => { setFilters({ from: '', to: '', minScore: '', q: '', limit: 10 }); setPage(1); }} className="btn btn-minor">Reset</button>
        <button onClick={doExport} className="btn" disabled={total === 0}>Export CSV</button>
        {user && ['recruiter', 'admin'].includes(user.role) && (
          <button className="btn btn-warning" onClick={reprocessAllFailed}>Retry All Failed</button>
        )}
      </div>

      <div style={{ marginBottom: 12 }}>
        <small className="muted">Tip: Search matches skills, matched skills, missing skills or filename. Use partial terms (e.g., "py" for "python").</small>
      </div>

      {loading ? (
        <p>Loading…</p>
      ) : (
        <div>
          <div style={{ marginBottom: 8 }}><strong>Total:</strong> {total}</div>
          {resumes.map(r => {
            const matchedArr = (r.matchedSkills && r.matchedSkills.length) ? r.matchedSkills : (r.skills && r.skills.length ? r.skills : []);
            const matchedText = matchedArr.length ? matchedArr.join(', ') : 'None';
            const missingText = (r.missingSkills && r.missingSkills.length) ? r.missingSkills.join(', ') : 'None';
            return (
              <div key={r._id} style={{ border: '1px solid #ddd', padding: 12, borderRadius: 6, marginBottom: 8 }}>
                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                  <div>
                    <strong>Score:</strong> {Math.round(r.score || 0)}%
                    {r.jobId && r.jobId.title && <span className="badge bg-info ms-2" style={{ marginLeft: 8 }}>Job: {r.jobId.title}</span>}
                  </div>
                  <div className="muted">{r.createdAt ? new Date(r.createdAt).toLocaleString() : ''}</div>
                </div>

                <div><strong>Matched:</strong> {matchedText}</div>
                <div><strong>Missing:</strong> {missingText}</div>
                <div><strong>Interview Status:</strong> {r.interviewStatus}</div>

                <div style={{ marginTop: 6, display: 'flex', alignItems: 'center', gap: 8 }}>
                  {r.fileName ? (
                    <a href={`http://localhost:5001/uploads/${r.fileName}`} target="_blank" rel="noreferrer">Download</a>
                  ) : (
                    <small className="muted">File: —</small>
                  )}

                  <button className="btn btn-minor" onClick={() => handleToggle(r)}>
                    {openId === r._id ? 'Hide' : 'View'}
                  </button>
                </div>

                {openId === r._id && (
                  <div style={{ marginTop: 8 }}>
                    <Result data={r} />

                    {user && (['recruiter', 'admin'].includes(user.role) || String(r.user) === String(user._id)) && (
                      <div style={{ marginTop: 8, display: 'flex', gap: 8, alignItems: 'center' }}>
                        <select value={currentEdit.status || r.interviewStatus} onChange={e => setCurrentEdit(c => ({ ...c, status: e.target.value }))}>
                          {STATUS_OPTIONS.map(s => <option value={s} key={s}>{s}</option>)}
                        </select>

                        <input type="date" value={currentEdit.interviewDate || (r.interviewDate ? r.interviewDate.slice(0, 10) : '')} onChange={e => setCurrentEdit(c => ({ ...c, interviewDate: e.target.value }))} />

                        <input type="text" placeholder="Note" value={currentEdit.note || r.interviewNotes || ''} onChange={e => setCurrentEdit(c => ({ ...c, note: e.target.value }))} />

                        <button className="btn" onClick={() => saveStatus(r._id)}>Save</button>
                      </div>
                    )}

                    {r.interviewHistory && r.interviewHistory.length > 0 && (
                      <div style={{ marginTop: 8 }}>
                        <strong>History:</strong>
                        <ul>
                          {r.interviewHistory.slice().reverse().map((h, i) => (
                            <li key={i}>{h.at ? new Date(h.at).toLocaleString() : ''} — <strong>{h.status}</strong>{h.note ? ` (${h.note})` : ''}</li>
                          ))}
                        </ul>
                      </div>
                    )}

                    {r.aiError && (
                      <div style={{ marginTop: 8 }}>
                        <strong style={{ color: '#c0392b' }}>AI Error:</strong>
                        <div className="error">{r.aiError}</div>
                        <div style={{ marginTop: 8 }}>
                          <button className="btn" onClick={() => retryAI(r._id)}>Retry AI</button>
                        </div>
                      </div>
                    )}
                  </div>
                )}
              </div>
            );
          })}

          <div style={{ display: 'flex', gap: 8, marginTop: 12 }}>
            <button className="btn btn-minor" disabled={page <= 1} onClick={() => setPage(p => Math.max(1, p - 1))}>Prev</button>
            <div style={{ padding: '6px 8px' }}>Page {page} of {pages}</div>
            <button className="btn btn-minor" disabled={page >= pages} onClick={() => setPage(p => Math.min(pages, p + 1))}>Next</button>
          </div>
        </div>
      )}
    </div>
  );
}

export default History;
